def get_coeffs(k):
    # coeffs[k][j] is a list of coefficients for a_{0,i}
    coeffs = {}
    coeffs[0] = {j: [1 if i == j else 0 for i in range(10)] for j in range(10)}

    for k_idx in range(1, k + 1):
        coeffs[k_idx] = {}
        # The number of terms at step k is 9*2^k + 1.
        # For small k, let's just use a reasonable size.
        num_terms = 10 * (2**k_idx)
        for j in range(num_terms):
            if j % 2 == 0:
                # a_{k, 2j} = a_{k-1, j}
                prev_j = j // 2
                coeffs[k_idx][j] = coeffs[k_idx-1].get(prev_j, [0]*10)
            else:
                # a_{k, 2j+1} = a_{k-1, j} + a_{k-1, j+1}
                prev_j1 = j // 2
                prev_j2 = prev_j1 + 1
                c1 = coeffs[k_idx-1].get(prev_j1, [0]*10)
                c2 = coeffs[k_idx-1].get(prev_j2, [0]*10)
                coeffs[k_idx][j] = [c1[i] + c2[i] for i in range(10)]
    return coeffs

