def solve_fast(n, k, target):
    count = {i: 1 for i in range(1, n + 1)}
    dp = {(i, i + 1): 1 for i in range(1, n)}

    for step in range(k):
        new_count = count.copy()
        new_dp = {}
        for (v1, v2), c in dp.items():
            v_sum = v1 + v2
            if v_sum <= target:
                new_count[v_sum] = new_count.get(v_sum, 0) + c
                new_dp[(v1, v_sum)] = new_dp.get((v1, v_sum), 0) + c
                new_dp[(v_sum, v2)] = new_dp.get((v_sum, v2), 0) + c
        count = new_count
        dp = new_dp
    return count.get(target, 0)

